-- Schema-only compatibility fixture: two reviewed compact hosted definitions.
-- ADR-0006 classifies both as formatting/comments only. No hosted rows, accounts,
-- migration history or grants are included. Use only in isolated rollback tests.
CREATE OR REPLACE FUNCTION private.evaluate_shadow_genome_v1(target_window_id uuid, target_genome_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare evaluation_window record; inserted_count integer:=0;
begin select * into evaluation_window from private.evaluation_windows as stored_window where stored_window.id=target_window_id; if evaluation_window.id is null then raise exception 'EvaluationWindow not found' using errcode='22023'; end if; if clock_timestamp()<evaluation_window.outcome_cutoff then raise exception 'EvaluationWindow has not matured yet' using errcode='55000'; end if; if exists(select 1 from private.genome_evaluations as existing where existing.evaluation_window_id=target_window_id and existing.genome_id=target_genome_id) then raise exception 'GenomeEvaluation already exists for this immutable window/genome' using errcode='23505'; end if;
with eligible_runs as materialized (select shadow.id as shadow_prediction_id,shadow.source_prediction_id,production.profile_id,production.requested_at,production.candidate_count from private.shadow_prediction_runs as shadow join private.prediction_runs as production on production.id=shadow.source_prediction_id where shadow.genome_id=target_genome_id and production.requested_at>=evaluation_window.prediction_from and production.requested_at<evaluation_window.prediction_until and shadow.as_of=production.requested_at and shadow.candidate_count=production.candidate_count),reversed_events as (select (event.properties->>'reversedEventId')::uuid as event_id from public.events as event where event.event_type='ITEM_INTERACTION_UNDONE' and event.occurred_at<=evaluation_window.outcome_cutoff and event.properties?'reversedEventId' and (event.properties->>'reversedEventId')~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'),exposed as materialized (select distinct eligible.source_prediction_id,eligible.shadow_prediction_id,eligible.profile_id,eligible.candidate_count,event.item_id from eligible_runs as eligible join public.events as event on event.prediction_id=eligible.source_prediction_id and event.profile_id=eligible.profile_id and event.event_type='ITEM_IMPRESSION' and event.item_id is not null and event.occurred_at>=eligible.requested_at and event.occurred_at<=evaluation_window.outcome_cutoff join private.prediction_candidates as production_candidate on production_candidate.prediction_id=eligible.source_prediction_id and production_candidate.item_id=event.item_id and production_candidate.selected_for_delivery),ranked_outcomes as (select exposed.source_prediction_id,exposed.profile_id,exposed.item_id,outcome.event_type,outcome.properties,row_number() over(partition by exposed.source_prediction_id,exposed.item_id order by private.outcome_priority_v1(outcome.event_type) desc,outcome.occurred_at desc,outcome.id desc) as outcome_rank from exposed join private.prediction_runs as production on production.id=exposed.source_prediction_id join public.events as outcome on outcome.prediction_id=exposed.source_prediction_id and outcome.profile_id=exposed.profile_id and outcome.item_id=exposed.item_id and outcome.occurred_at>=production.requested_at and outcome.occurred_at<=evaluation_window.outcome_cutoff and private.outcome_priority_v1(outcome.event_type)>0 where not exists(select 1 from reversed_events where reversed_events.event_id=outcome.id)),labelled as materialized (select exposed.source_prediction_id,exposed.profile_id,exposed.item_id,exposed.candidate_count,production_candidate.final_rank as production_rank,shadow_candidate.shadow_rank,private.outcome_reward_v1(ranked_outcomes.event_type,ranked_outcomes.properties) as reward from exposed join ranked_outcomes on ranked_outcomes.source_prediction_id=exposed.source_prediction_id and ranked_outcomes.item_id=exposed.item_id and ranked_outcomes.outcome_rank=1 join private.prediction_candidates as production_candidate on production_candidate.prediction_id=exposed.source_prediction_id and production_candidate.item_id=exposed.item_id join private.shadow_prediction_candidates as shadow_candidate on shadow_candidate.shadow_prediction_id=exposed.shadow_prediction_id and shadow_candidate.item_id=exposed.item_id),contributions as materialized (select labelled.*,labelled.reward*case when labelled.candidate_count<=1 then 1.0 else 1.0-((labelled.production_rank-1)::double precision/(labelled.candidate_count-1)::double precision) end as production_contribution,labelled.reward*case when labelled.candidate_count<=1 then 1.0 else 1.0-((labelled.shadow_rank-1)::double precision/(labelled.candidate_count-1)::double precision) end as challenger_contribution from labelled),sample_scopes as (select 'GLOBAL'::text as scope_type,'GLOBAL'::text as scope_key,contributions.* from contributions union all select 'PROFILE'::text,contributions.profile_id::text,contributions.* from contributions),exposure_scopes as (select 'GLOBAL'::text as scope_type,'GLOBAL'::text as scope_key,count(*)::integer as exposed_count from exposed union all select 'PROFILE'::text,exposed.profile_id::text,count(*)::integer from exposed group by exposed.profile_id),aggregated as (select sample_scopes.scope_type,sample_scopes.scope_key,avg(sample_scopes.production_contribution) as production_metric,avg(sample_scopes.challenger_contribution) as challenger_metric,avg(sample_scopes.challenger_contribution-sample_scopes.production_contribution) as raw_advantage,count(*)::integer as outcome_count,count(distinct sample_scopes.source_prediction_id)::integer as prediction_count,count(distinct sample_scopes.profile_id)::integer as profile_count,case when count(*)>1 then stddev_samp(sample_scopes.challenger_contribution-sample_scopes.production_contribution)/sqrt(count(*)::double precision) else null end as standard_error from sample_scopes group by sample_scopes.scope_type,sample_scopes.scope_key),global_stats as (select aggregated.raw_advantage from aggregated where aggregated.scope_type='GLOBAL' and aggregated.scope_key='GLOBAL')
insert into private.genome_evaluations(evaluation_window_id,genome_id,scope_type,scope_key,production_metric,challenger_metric,raw_advantage,shrunk_advantage,outcome_count,exposed_count,prediction_count,profile_count,coverage,standard_error,eligibility_reason,metrics)
select target_window_id,target_genome_id,aggregated.scope_type,aggregated.scope_key,aggregated.production_metric,aggregated.challenger_metric,aggregated.raw_advantage,case when aggregated.scope_type='PROFILE' then (aggregated.outcome_count::double precision/(aggregated.outcome_count::double precision+30.0))*aggregated.raw_advantage+(1.0-(aggregated.outcome_count::double precision/(aggregated.outcome_count::double precision+30.0)))*coalesce((select raw_advantage from global_stats),0.0) else aggregated.raw_advantage end,aggregated.outcome_count,exposure_scopes.exposed_count,aggregated.prediction_count,aggregated.profile_count,aggregated.outcome_count::double precision/greatest(1,exposure_scopes.exposed_count)::double precision,aggregated.standard_error,'MATURE_COMPARABLE_EXPOSED_OUTCOME',jsonb_build_object('metricVersion',evaluation_window.metric_version,'rewardVersion',evaluation_window.reward_version,'counterfactualLimit','UNEXPOSED_SHADOW_ITEMS_UNLABELLED','profileShrinkageK',30,'productionMetric',aggregated.production_metric,'challengerMetric',aggregated.challenger_metric,'rawAdvantage',aggregated.raw_advantage,'standardError',aggregated.standard_error) from aggregated join exposure_scopes on exposure_scopes.scope_type=aggregated.scope_type and exposure_scopes.scope_key=aggregated.scope_key where exposure_scopes.exposed_count>=evaluation_window.minimum_exposure_count;
get diagnostics inserted_count=row_count; if inserted_count=0 then insert into private.genome_evaluations(evaluation_window_id,genome_id,scope_type,scope_key,production_metric,challenger_metric,raw_advantage,shrunk_advantage,outcome_count,exposed_count,prediction_count,profile_count,coverage,standard_error,eligibility_reason,metrics) values(target_window_id,target_genome_id,'GLOBAL','GLOBAL',null,null,null,null,0,0,0,0,0.0,null,'NO_MATURE_COMPARABLE_OUTCOMES',jsonb_build_object('metricVersion',evaluation_window.metric_version,'rewardVersion',evaluation_window.reward_version,'counterfactualLimit','UNEXPOSED_SHADOW_ITEMS_UNLABELLED')); inserted_count:=1; end if; return jsonb_build_object('evaluationsInserted',inserted_count); end; $function$;

CREATE OR REPLACE FUNCTION private.process_shadow_prediction_jobs_v1(batch_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare selected_job record; source_run record; genome record; shadow_run_id uuid; processed_count integer:=0; failed_count integer:=0;
begin if batch_limit<1 or batch_limit>250 then raise exception 'Batch limit must be between 1 and 250' using errcode='22023'; end if;
for selected_job in select job.id,job.source_prediction_id,job.genome_id from private.shadow_prediction_jobs as job where job.status='QUEUED' order by job.enqueued_at,job.id limit batch_limit for update skip locked loop
update private.shadow_prediction_jobs set status='PROCESSING',attempts=attempts+1,started_at=clock_timestamp(),last_error=null where id=selected_job.id;
begin select * into source_run from private.prediction_runs as production_run where production_run.id=selected_job.source_prediction_id; if source_run.id is null or source_run.candidate_count<=0 or source_run.result_count<=0 then raise exception 'Source PredictionRun is missing or incomplete'; end if; select * into genome from private.predictor_genomes as stored_genome where stored_genome.id=selected_job.genome_id; if genome.id is null then raise exception 'PredictorGenome is missing'; end if; shadow_run_id:=gen_random_uuid();
insert into private.shadow_prediction_runs(id,source_prediction_id,genome_id,profile_id,actor_user_id,session_id,as_of,requested_item_type,discovery_mode,context,state_snapshot,source_model_version,source_policy_version,code_version,feature_version,memory_version,outcome_version,reward_version,candidate_count,hypothetical_result_count) values(shadow_run_id,source_run.id,genome.id,source_run.profile_id,source_run.actor_user_id,source_run.session_id,source_run.requested_at,source_run.requested_item_type,source_run.discovery_mode,source_run.context,source_run.state_snapshot,source_run.model_version,source_run.policy_version,genome.code_version,genome.feature_version,genome.memory_version,genome.outcome_version,genome.reward_version,source_run.candidate_count,source_run.result_count);
insert into private.shadow_prediction_candidates(shadow_prediction_id,item_id,source_rank,production_final_rank,shadow_rank,source_score,production_final_score,shadow_score,scenario_score,hypothetical_selected,explanation)
with rescored as (select production_candidate.*,private.shadow_candidate_score_v1(source_run.discovery_mode,production_candidate.explanation,production_candidate.scenario_score,genome.config) as challenger_score from private.prediction_candidates as production_candidate where production_candidate.prediction_id=source_run.id),reranked as (select rescored.*,row_number() over(order by rescored.challenger_score desc,rescored.item_id)::integer as challenger_rank from rescored)
select shadow_run_id,reranked.item_id,reranked.source_rank,reranked.final_rank,reranked.challenger_rank,reranked.source_score,reranked.final_score,reranked.challenger_score,reranked.scenario_score,reranked.challenger_rank<=source_run.result_count,jsonb_build_object('version','shadow-prediction-v1','sourcePredictionId',source_run.id,'genomeKey',genome.genome_key,'genomeId',genome.id,'asOf',source_run.requested_at,'input',jsonb_build_object('productionExplanation',reranked.explanation,'storedScenarioScore',reranked.scenario_score),'score',reranked.challenger_score,'productionRank',reranked.final_rank,'shadowRank',reranked.challenger_rank,'hypotheticalOnly',true) from reranked;
if (select count(*) from private.shadow_prediction_candidates as stored_shadow where stored_shadow.shadow_prediction_id=shadow_run_id)<>source_run.candidate_count then raise exception 'Shadow candidate count does not match frozen source pool'; end if;
update private.shadow_prediction_jobs set status='DONE',finished_at=clock_timestamp() where id=selected_job.id; processed_count:=processed_count+1;
exception when others then update private.shadow_prediction_jobs set status='FAILED',finished_at=clock_timestamp(),last_error=left(sqlerrm,1000) where id=selected_job.id; failed_count:=failed_count+1; end; end loop;
return jsonb_build_object('processed',processed_count,'failed',failed_count); end; $function$;
